static inline microblaze_reg_t microblaze_get_syscall_arg(struct pt_regs *regs, /* <=== microblaze_get_syscall_arg */ 
							  unsigned int n)
{
	switch (n) {
	case 5: return regs->r10;
	case 4: return regs->r9;
	case 3: return regs->r8;
	case 2: return regs->r7;
	case 1: return regs->r6;
	case 0: return regs->r5;
	default:
		BUG();
	}
	return ~0;
}

